"""test_views — the generated workspace files and ROOKERY.md (T009; D7, D15; FR-007, FR-010, FR-013, FR-030)."""
import json
import os
import shutil
import subprocess
import sys
import tempfile
import unittest

import cli_init
import rookery_team
import rookery_views

CONFIG = {"launch": {"tmux-pane": {}}, "default_binding": "tmux-pane"}
TEAM = {
    "session": "auth-fix",
    "task": "Fix the token refresh race.",
    "agents": [
        {"name": "scout", "harness": "claude", "role": "reader",
         "persona": "You read code and report. You do not edit.",
         "scope": {"does": ["read the auth module"], "does_not": ["edit files", "run the server"]}},
        {"name": "fixer", "harness": "claude", "role": "writer", "task_id": "T1", "repo": None},
    ],
}
OTHER_TEAM_NAME = "outsider"
GENERATED = ["CLAUDE.md", "AGENTS.md", "CONTEXT.md", "_config/persona.md",
             "_config/scope-card.md", "_config/system-prompt.md"]


class Base(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp, True)
        self.root = os.path.join(self.tmp, "root")
        os.makedirs(self.root)
        self.host = os.path.join(self.tmp, "host")
        os.makedirs(self.host)
        tf = os.path.join(self.tmp, "team.json")
        spec = json.loads(json.dumps(TEAM))
        spec["agents"][1].pop("repo")
        with open(tf, "w") as fh:
            json.dump(spec, fh)
        self.team = rookery_team.load(tf, CONFIG)
        self.session = {"name": "auth-fix", "session_id": "s-1"}

    def run_agent(self, i, command="up"):
        a = dict(self.team["agents"][i])
        a["agent_id"] = f"id-{a['name']}"
        return rookery_views.workspace_files(self.root, self.session, a, self.team, self.host, command)

    def read(self, ws, rel):
        with open(os.path.join(ws, rel), encoding="utf-8") as fh:
            return fh.read()


class WorkspaceFiles(Base):
    def test_each_item_exists_with_generated_line(self):
        ws = self.run_agent(0)
        self.assertEqual(ws, os.path.join(self.root, "agents", "auth-fix", "scout"))
        for rel in GENERATED:
            first = self.read(ws, rel).splitlines()[0]
            self.assertRegex(first, r"^<!-- generated by rookery up at .+; do not edit -->$", rel)
        for d in ("runs", "outbox", "state"):
            self.assertTrue(os.path.isdir(os.path.join(ws, d)), d)

    def test_claude_md_content(self):
        ws = self.run_agent(0)
        text = self.read(ws, "CLAUDE.md")
        for needle in ("scout", "id-scout", "auth-fix", "reader", "claude", "rookery inbox",
                       "rookery peek", "rookery ack", "rookery send", "ROOKERY.md", "CONTEXT.md", "_config/"):
            self.assertIn(needle, text)
        self.assertIn("```rookery", text)
        self.assertNotIn("@", self.read(ws, "AGENTS.md"))

    def test_second_call_keeps_agent_files_and_restores_generated(self):
        ws = self.run_agent(1)
        paths = {"runs/T1/HANDOFF.md": "# mine\n", "runs/T1/02_work/x.txt": "work",
                 "outbox/o1.json": "{}", "state/turn.json": "{}"}
        for rel, body in paths.items():
            p = os.path.join(ws, rel)
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "w") as fh:
                fh.write(body)
        good = self.read(ws, "CLAUDE.md").split("\n", 1)[1]
        with open(os.path.join(ws, "CLAUDE.md"), "w") as fh:
            fh.write("hand edit\n")
        self.run_agent(1)
        for rel, body in paths.items():
            self.assertEqual(self.read(ws, rel), body)
        self.assertEqual(self.read(ws, "CLAUDE.md").split("\n", 1)[1], good)
        self.assertNotIn("hand edit", self.read(ws, "CLAUDE.md"))

    def test_scope_card_negative_and_same_team_only(self):
        ws = self.run_agent(0)
        text = self.read(ws, "_config/scope-card.md")
        self.assertIn("Does NOT do", text)
        self.assertIn("edit files", text)
        self.assertIn("read the auth module", text)
        self.assertIn("fixer", text)
        self.assertNotIn(OTHER_TEAM_NAME, text)
        # a second, unrelated team on disk never leaks in
        self.run_agent(1)
        fixer = self.read(os.path.join(self.root, "agents", "auth-fix", "fixer"), "_config/scope-card.md")
        self.assertIn("scout", fixer)
        self.assertIn("Does NOT do", fixer)

    def test_no_mcp_names(self):
        for i in (0, 1):
            ws = self.run_agent(i)
            for rel in GENERATED:
                body = self.read(ws, rel)
                for bad in ("check_inbox", "await_message", "mcp__"):
                    self.assertNotIn(bad, body, rel)
        rookery_views.rookery_md(self.root)
        self.assertNotIn("mcp__", self.read(self.root, "ROOKERY.md"))

    def test_no_claude_or_agents_md_above_workspace(self):
        self.run_agent(0)
        self.run_agent(1)
        rookery_views.rookery_md(self.root)
        for d in (self.root, os.path.join(self.root, "agents"), os.path.join(self.root, "agents", "auth-fix")):
            for n in ("CLAUDE.md", "AGENTS.md"):
                self.assertFalse(os.path.exists(os.path.join(d, n)), os.path.join(d, n))
        self.assertTrue(os.path.exists(os.path.join(self.root, "ROOKERY.md")))
        self.assertRegex(self.read(self.root, "ROOKERY.md").splitlines()[0],
                         r"^<!-- generated by rookery up at .+; do not edit -->$")

    def test_context_md_handoff_rule(self):
        text = self.read(self.run_agent(1), "CONTEXT.md")
        for needle in ("01_intake", "02_work", "03_report", "HANDOFF.md", "Last thing I did",
                       "State now", "What is left", "Open threads"):
            self.assertIn(needle, text)

    @unittest.skipUnless(shutil.which("ste-lint"), "ste-lint missing")
    def test_ste_lint_passes(self):
        glossary = os.path.join(os.path.dirname(os.path.abspath(__file__)), "ste-glossary.txt")
        files = []
        for i in (0, 1):
            ws = self.run_agent(i)
            files += [os.path.join(ws, r) for r in GENERATED]
        rookery_views.rookery_md(self.root)
        files.append(os.path.join(self.root, "ROOKERY.md"))
        for f in files:
            r = subprocess.run(["ste-lint", f, "--max-score", "2.0", "--glossary", glossary],
                               capture_output=True, text=True)
            self.assertEqual(r.returncode, 0, f"{f}\n{r.stdout}{r.stderr}")


def _handlers(data, event):
    return [h for g in data["hooks"][event] for h in g["hooks"] if cli_init._is_rookery(h)]


class SettingsJson(Base):
    def setUp(self):
        super().setUp()
        self.out = os.path.join(self.tmp, "ws", "_config", "settings.json")

    def load(self, p):
        with open(p, encoding="utf-8") as fh:
            return json.load(fh)

    def test_matches_merge_hooks_text_and_permissions(self):
        fresh = os.path.join(self.tmp, "fresh", ".claude", "settings.json")
        cli_init.merge_hooks(fresh, "app")
        self.assertEqual(rookery_views.settings_json(self.out, "app"), self.out)
        got, want = self.load(self.out), self.load(fresh)
        for event, _sub in cli_init.HOOK_EVENTS:
            self.assertEqual(_handlers(got, event)[0]["command"].encode(),
                             _handlers(want, event)[0]["command"].encode())
        self.assertIn("Bash(rookery inbox:*)", got["permissions"]["allow"])

    def _repo(self, body):
        repo = os.path.join(self.tmp, "repo")
        os.makedirs(os.path.join(repo, ".claude"))
        p = os.path.join(repo, ".claude", "settings.json")
        with open(p, "w") as fh:
            fh.write(body)
        return repo, p

    def test_repo_committed_text_is_copied_once(self):
        committed = os.path.join(self.tmp, "c", ".claude", "settings.json")
        cli_init.merge_hooks(committed, "app")
        data = self.load(committed)
        _handlers(data, "Stop")[0].update(command="/opt/bin/rookery hook stop --project app", timeout=30)
        data["hooks"]["Stop"][0]["matcher"] = "*"
        repo, rp = self._repo(json.dumps(data, indent=2))
        before = open(rp, "rb").read()
        rookery_views.settings_json(self.out, "app", repo=repo)
        got = self.load(self.out)
        self.assertEqual([h["command"] for h in _handlers(got, "Stop")],
                         ["/opt/bin/rookery hook stop --project app"])
        self.assertEqual(_handlers(got, "Stop")[0], _handlers(data, "Stop")[0])
        self.assertEqual(got["hooks"]["Stop"][0]["matcher"], "*")
        self.assertEqual(len([h for g in got["hooks"]["Stop"] for h in g["hooks"]]), 1)
        self.assertEqual(_handlers(got, "SessionStart")[0]["command"], "rookery hook session-start --project app")
        self.assertEqual(_handlers(got, "UserPromptSubmit")[0]["command"], "rookery hook prompt --project app")
        self.assertEqual(open(rp, "rb").read(), before)

    def test_invalid_repo_file_falls_back(self):
        repo, _ = self._repo("{not json")
        rookery_views.settings_json(self.out, "app", repo=repo)
        self.assertEqual(_handlers(self.load(self.out), "Stop")[0]["command"], "rookery hook stop --project app")
        rookery_views.settings_json(self.out, "app", repo=os.path.join(self.tmp, "nope"))


if __name__ == "__main__":
    unittest.main()
